('111.7.b.10.A',3,'Which tax is paid by people who own land or buildings?','["income tax", "sales tax", "payroll tax", "property tax"]'::jsonb,3,'Property tax is based on what a person owns.','original'),
('111.7.b.10.A',3,'Which tax is based on the money a person earns?','["income tax", "tax on groceries only", "sales tax", "property tax"]'::jsonb,0,'Income tax is a percent of earnings.','original'),
('111.7.b.10.A',3,'Which tax is taken from a worker''s paycheck to help pay for programs like Social Security and Medicare?','["property tax", "payroll tax", "gas tax", "sales tax"]'::jsonb,1,'Payroll taxes come out of paychecks.','original'),
('111.7.b.10.A',4,'A family pays tax on their house every year. What kind of tax is that?','["payroll tax", "income tax", "property tax", "sales tax"]'::jsonb,2,'A tax on owned property is property tax.','original'),
('111.7.b.10.B',3,'What is gross income?','["money left after taxes", "money saved in a bank", "money spent each month", "all the money earned before anything is taken out"]'::jsonb,3,'Gross income is the total before deductions such as taxes.','original'),
('111.7.b.10.B',3,'What is net income?','["the money left after taxes and deductions are taken out", "all the money earned before taxes", "the price of an item", "the money you owe"]'::jsonb,0,'Net income is your take-home pay.','original'),
('111.7.b.10.C',3,'Which payment method takes money directly from your bank account when you buy something?','["a coupon", "debit card", "credit card", "a gift wrapper"]'::jsonb,1,'A debit card pays with money you already have in the bank.','original'),
('111.7.b.10.C',3,'Which payment method lets you borrow money that you must pay back later?','["a gift card with money loaded", "debit card", "credit card", "cash"]'::jsonb,2,'A credit card is a loan; you must pay it back, often with interest.','original'),
('111.7.b.10.C',3,'What is one disadvantage of using a credit card?','["you can never buy anything", "it always takes money from your bank right away", "it never needs to be paid", "you may owe interest if you do not pay the full bill"]'::jsonb,3,'Unpaid credit card balances can grow with interest.','original'),
('111.7.b.10.C',3,'What is one advantage of paying with cash?','["you can only spend the money you have", "it earns interest", "it leaves a record on your bank account", "you can borrow more than you have"]'::jsonb,0,'Cash helps you stay within what you have.','original'),
('111.7.b.10.C',3,'A check is a written order for a bank to pay money from which place?','["a store''s cash register", "your checking account", "the post office", "a credit card company''s office"]'::jsonb,1,'A check pulls money from a checking account.','original'),
('111.7.b.10.C',4,'Which is an advantage of paying electronically with a debit card or app?','["it lets you spend without limit", "it never requires money in an account", "it is quick and leaves a record of the purchase", "it can never be lost or misused"]'::jsonb,2,'Electronic payments are convenient and create records, but you still need the money.','original'),
('111.7.b.10.D',3,'Why should a family keep records of bills and receipts?','["to avoid paying taxes", "to get more money", "to make bills smaller", "to track spending and prove payments"]'::jsonb,3,'Records help track money and show what was paid.','original'),
('111.7.b.10.D',3,'Which is a good way to keep financial records organized?','["put bills and receipts in labeled folders or a spreadsheet", "keep them in a random pile", "never write anything down", "throw receipts away immediately"]'::jsonb,0,'Organized records are easy to find and use.','original'),
('111.7.b.10.D',3,'How long should you keep a receipt for a big purchase you might need to return or use for a warranty?','["one minute", "until the return or warranty period ends", "only until you get home and then toss it", "it never needs to be kept"]'::jsonb,1,'Keep the receipt as proof while a return or warranty could apply.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g5_math_v1'
